#!/usr/bin/env node
/**
 * Copies Legal's final beta policies into app/legal/en/ so the app (which
 * Vercel builds from app/ alone) can render them as trust pages.
 *
 *   source: ../20_Legal_Compliance/final/   (owned by Legal; read-only here)
 *   target: legal/en/<slug>.md              (generated; do not edit by hand)
 *
 * What it changes, and nothing else:
 *   - removes the "Internal header" blockquote and the `---` rule after it
 *     (Legal's own instruction: "remove the blockquotes before publishing");
 *   - drops the leading "# PranaDin (प्राणदिन): " prefix from the title;
 *   - for the health disclaimer, keeps only section B (the full page).
 *     Section A is the onboarding screen and C the caution block; those are
 *     UI copy that Content and Dev-2 render elsewhere;
 *   - adds front matter (id, title, lang, version, status, basis).
 * Fill-ins such as ⟦contact email⟧ stay visible on purpose (D-022).
 *
 * Run: node scripts/sync-legal.mjs   (re-run whenever Legal updates a file)
 */
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";

const root = path.resolve(import.meta.dirname, "..");
const src = path.resolve(root, "..", "20_Legal_Compliance", "final");
const out = path.join(root, "legal", "en");

const FILES = [
  { from: "privacy-notice.md", slug: "privacy" },
  { from: "terms-of-use.md", slug: "terms" },
  { from: "health-and-content-disclaimer.md", slug: "help", section: /^## B\. .*$/m, until: /^## C\. /m },
];

if (!fs.existsSync(src)) {
  console.error(`sync-legal: ${src} not found (run from the HQ checkout).`);
  process.exit(1);
}
fs.mkdirSync(out, { recursive: true });

for (const f of FILES) {
  const raw = fs.readFileSync(path.join(src, f.from), "utf8").replace(/^﻿/, "").replace(/\r\n/g, "\n");
  const lines = raw.split("\n");
  const titleLine = lines.find((l) => l.startsWith("# "));
  if (!titleLine) throw new Error(`${f.from}: no "# " title`);
  const title = titleLine.replace(/^#\s+/, "").replace(/^PranaDin \(प्राणदिन\):\s*/, "").trim();
  const versionLine = lines.find((l) => /Version:/.test(l)) ?? "";

  let body = lines.filter((l) => !l.startsWith(">")).join("\n");
  body = body.replace(titleLine, "").replace(/^\s*---\s*$/m, "");
  if (f.section) {
    const start = body.search(f.section);
    const end = body.search(f.until);
    if (start < 0 || end < 0) throw new Error(`${f.from}: section markers not found`);
    body = `${versionLine}\n\n${body.slice(start, end).replace(f.section, "")}`;
  }
  body = body.replace(/\n{3,}/g, "\n\n").trim() + "\n";

  const sha = createHash("sha256").update(raw).digest("hex").slice(0, 12);
  const fm = [
    "---",
    `id: page.${f.slug}`,
    `title: ${title}`,
    "lang: en",
    "version: 2026-11-14.1",
    "status: final",
    `basis: "Generated by scripts/sync-legal.mjs from 20_Legal_Compliance/final/${f.from} (sha256 ${sha}). Do not edit."`,
    "---",
    "",
  ].join("\n");
  fs.writeFileSync(path.join(out, `${f.slug}.md`), fm + body);
  console.log(`legal/en/${f.slug}.md  <-  ${f.from}`);
}
